## Java Implementation

```java
import java.util.*;

public class CommonElements {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int m = sc.nextInt();

        int[] A = new int[n];
        int[] B = new int[m];

        for (int i = 0; i < n; i++) A[i] = sc.nextInt();
        for (int i = 0; i < m; i++) B[i] = sc.nextInt();

        Arrays.sort(A);
        Arrays.sort(B);

        int i = 0, j = 0;
        boolean found = false;
        StringBuilder sb = new StringBuilder();

        while (i < n && j < m) {
            if (A[i] == B[j]) {
                sb.append(A[i]).append(' ');
                found = true;
                int val = A[i];
                while (i < n && A[i] == val) i++;
                while (j < m && B[j] == val) j++;
            } else if (A[i] < B[j]) {
                i++;
            } else {
                j++;
            }
        }

        if (!found) System.out.println("No common elements");
        else System.out.println(sb.toString().trim());
    }
}
```

Compile & run:

```bash
javac CommonElements.java
java CommonElements
```

